CREATE OR ALTER FUNCTION dbo.fn_OrderTotalWithTax
(
    @SubTotal DECIMAL(18, 2),
    @TaxRate  DECIMAL(5, 4)
)
RETURNS DECIMAL(18, 2)
AS
BEGIN
    RETURN @SubTotal * (1 + @TaxRate);
END;
GO

CREATE OR ALTER FUNCTION dbo.fn_OrdersAbove
(
    @MinimumTotal DECIMAL(18, 2)
)
RETURNS TABLE
AS
RETURN
(
    SELECT SalesOrderID, CustomerID, OrderDate, TotalDue
    FROM sales.SalesOrderHeader
    WHERE TotalDue > @MinimumTotal
);
GO

SELECT *
FROM dbo.fn_OrdersAbove(1000.00);
